53	impl ApplicationHandler for App {
54	    fn resumed(&mut self, event_loop: &ActiveEventLoop) {
55	        if self.state.is_some() {
56	            return;
57	        }
58	
59	        let window_attrs = Window::default_attributes().with_title("BetterArc");
60	        let window = Arc::new(
61	            event_loop
62	                .create_window(window_attrs)
63	                .expect("failed to create window"),
64	        );
65	
66	        // Load chart: from CLI path or embedded test chart
67	        let chart_str = if let Some(path) = &self.chart_path {
68	            std::fs::read_to_string(path).expect("failed to read chart file")
69	        } else {
70	            include_str!("../assets/charts/test.aff").to_string()
71	        };
72	        let chart = crate::chart::parse(&chart_str).expect("failed to parse chart");
73	        log::info!(
74	            "chart loaded: {} taps, {} holds, {} arcs",
75	            chart.groups[0].taps.len(),
76	            chart.groups[0].holds.len(),
77	            chart.groups[0].arcs.len(),
78	        );
79	
80	        let mut clock = GameClock::new(&chart);
81	
82	        // Load audio if available
83	        if let Some(audio_path) = &self.audio_path {
84	            let path = Path::new(audio_path);
85	            if path.exists() {
86	                match AudioEngine::play_ogg(path, LEAD_IN_MS) {
87	                    Ok(engine) => {
88	                        log::info!("audio loaded from {}", audio_path);
89	                        clock.set_audio(engine);
90	                    }
91	                    Err(e) => log::error!("failed to load audio: {e}"),
92	                }
93	            } else {
94	                log::warn!("audio file not found: {}", audio_path);
95	            }
96	        }
97	
98	        let input = InputManager::new();
99	        let judge = GreedyJudge::new(&chart);
100	        let hitsound = HitsoundEngine::new();
101	        if hitsound.is_some() {
102	            log::info!("hitsound engine initialized");
103	        }
104	        let assets_dir = PathBuf::from("assets");
105	        let gpu = pollster::block_on(Gpu::new(window.clone(), &assets_dir));
106	
107	        self.state = Some(AppState {
108	            window,
109	            gpu,
110	            chart,
111	            clock,
112	            input,
113	            judge,
114	            hit_effects: Vec::new(),
115	            hitsound,
116	            last_combo: 0,
117	            combo_flash: 0.0,
118	            last_frame: Instant::now(),
119	            result_shown: false,
120	        });
121	        log::info!("app initialized");
122	    }
123	
124	    fn window_event(
125	        &mut self,
126	        event_loop: &ActiveEventLoop,
127	        _window_id: WindowId,
128	        event: WindowEvent,
129	    ) {
130	        let Some(state) = &mut self.state else {
131	            return;
132	        };
133	
134	        match event {
135	            WindowEvent::CloseRequested => {
136	                event_loop.exit();
137	            }
138	            WindowEvent::Resized(size) => {
139	                if size.width > 0 && size.height > 0 {
140	                    state.gpu.resize(size.width, size.height);
141	                }
142	            }
143	            WindowEvent::KeyboardInput { event, .. } => {
144	                if state.result_shown {
145	                    if event.state == ElementState::Pressed && !event.repeat {
146	                        event_loop.exit();
147	                    }
148	                } else if let Some(lane) = input::physical_key_to_lane(&event.physical_key) {
149	                    if event.state == ElementState::Pressed && !event.repeat {
150	                        let time = state.clock.current_time_ms();
151	                        state.input.key_down(lane, time);
152	                    } else if event.state == ElementState::Released {
153	                        state.input.key_up(lane);
154	                    }
155	                }
156	            }
157	            WindowEvent::RedrawRequested => {
158	                let current_time = state.clock.current_time_ms();
159	
160	                // Check for results trigger
161	                if !state.result_shown {
162	                    let s = &state.judge.score;
163	                    if s.total_notes > 0 && s.judged_count() == s.total_notes {
164	                        state.result_shown = true;
165	                        state.gpu.show_results(&state.judge.score);
166	                        log::info!("results: score={} pure={}(+{}) far={} lost={} max_combo={}",
167	                            s.score(), s.pure_max + s.pure, s.pure_max, s.far, s.lost, s.max_combo);
168	                    }
169	                }
170	
171	                if state.result_shown {
172	                    state.gpu.render();
173	                    state.window.request_redraw();
174	                    return;
175	                }
176	
177	                // Process inputs through judgment
178	                let inputs = state.input.drain();
179	                state.judge.update(current_time, &inputs, &state.input);
180	
181	                // Collect hit effects and trigger hitsounds from recent judgments
182	                for result in &state.judge.recent {
183	                    if result.grade != Grade::Lost {
184	                        state.hit_effects.push(HitEffect {
185	                            lane: result.lane,
186	                            time_ms: result.time_ms,
187	                            grade: result.grade,
188	                        });
189	
190	                        if let Some(hs) = &state.hitsound {
191	                            match result.kind {
192	                                NoteKind::Tap | NoteKind::HoldStart => hs.play_tap(),
193	                                NoteKind::ArcTap => hs.play_arc(),
194	                                NoteKind::HoldTick => {}
195	                            }
196	                        }
197	                    }
198	                }
199	
200	                // Log score on judgment events
201	                if !state.judge.recent.is_empty() {
202	                    let s = &state.judge.score;
203	                    log::info!(
204	                        "score: {} | combo: {} | P:{}/p:{}/F:{}/L:{} [{}/{}]",
205	                        s.score(),
206	                        s.combo,
207	                        s.pure_max,
208	                        s.pure,
209	                        s.far,
210	                        s.lost,
211	                        s.judged_count(),
212	                        s.total_notes,
213	                    );
214	                    state.judge.recent.clear();
215	                }
216	
217	                // Update combo flash
218	                let now = Instant::now();
219	                let dt = now.duration_since(state.last_frame).as_secs_f32();
220	                state.last_frame = now;
221	
222	                let combo = state.judge.score.combo;
223	                if state.last_combo > 0 && combo == 0 {
224	                    state.combo_flash = 1.0;
225	                }
226	                state.last_combo = combo;
227	                state.combo_flash = (state.combo_flash - dt / 0.1).max(0.0);
228	
229	                // Update HUD
230	                state.gpu.update_hud(combo, state.judge.score.score(), state.combo_flash);
231	
232	                // Expire old hit effects (>300ms)
233	                state
234	                    .hit_effects
235	                    .retain(|e| current_time - e.time_ms < 300);
236	
237	                state.gpu.update_notes(
238	                    &state.chart,
239	                    &state.clock,
240	                    current_time,
241	                    &state.judge,
242	                    &state.hit_effects,
243	                );
244	                state.gpu.render();
245	                state.window.request_redraw();
246	            }
247	            _ => {}
248	        }
249	    }
250	}
251	
252	pub fn run_app() {
253	    let args: Vec<String> = std::env::args().collect();
254	    // Usage: better-arc [chart.aff] [audio.ogg]
255	    let chart_path = args.get(1).cloned();
256	    let audio_path = args.get(2).cloned();
257	
258	    if chart_path.is_some() {
259	        log::info!("chart: {}", chart_path.as_deref().unwrap());
260	    }
261	    if audio_path.is_some() {
262	        log::info!("audio: {}", audio_path.as_deref().unwrap());
263	    }
264	
265	    let event_loop = EventLoop::new().expect("failed to create event loop");
266	    let mut app = App::new(chart_path, audio_path);
267	    event_loop.run_app(&mut app).expect("event loop error");
268	}
