146	impl Gpu {
147	    pub async fn new(window: Arc<Window>, assets_dir: &Path) -> Self {
148	        let size = window.inner_size();
149	
150	        let instance = wgpu::Instance::new(wgpu::InstanceDescriptor {
151	            backends: wgpu::Backends::all(),
152	            ..Default::default()
153	        });
154	
155	        let surface = instance
156	            .create_surface(window)
157	            .expect("failed to create surface");
158	
159	        let adapter = instance
160	            .request_adapter(&wgpu::RequestAdapterOptions {
161	                power_preference: wgpu::PowerPreference::HighPerformance,
162	                compatible_surface: Some(&surface),
163	                force_fallback_adapter: false,
164	            })
165	            .await
166	            .expect("no suitable GPU adapter");
167	
168	        log::info!("GPU: {:?}", adapter.get_info());
169	
170	        let limits = if cfg!(target_os = "android") {
171	            wgpu::Limits::downlevel_defaults()
172	        } else {
173	            wgpu::Limits::default()
174	        }
175	        .using_resolution(adapter.limits());
176	
177	        let (device, queue) = adapter
178	            .request_device(
179	                &wgpu::DeviceDescriptor {
180	                    label: Some("better-arc"),
181	                    required_features: wgpu::Features::empty(),
182	                    required_limits: limits,
183	                    ..Default::default()
184	                },
185	                None,
186	            )
187	            .await
188	            .expect("failed to create device");
189	
190	        // Surface
191	        let caps = surface.get_capabilities(&adapter);
192	        let format = caps
193	            .formats
194	            .iter()
195	            .find(|f| f.is_srgb())
196	            .copied()
197	            .unwrap_or(caps.formats[0]);
198	
199	        let config = wgpu::SurfaceConfiguration {
200	            usage: wgpu::TextureUsages::RENDER_ATTACHMENT,
201	            format,
202	            width: size.width.max(1),
203	            height: size.height.max(1),
204	            present_mode: wgpu::PresentMode::AutoVsync,
205	            alpha_mode: caps.alpha_modes[0],
206	            view_formats: vec![],
207	            desired_maximum_frame_latency: 2,
208	        };
209	        surface.configure(&device, &config);
210	
211	        // Shader
212	        let shader = device.create_shader_module(wgpu::ShaderModuleDescriptor {
213	            label: Some("shader"),
214	            source: wgpu::ShaderSource::Wgsl(SHADER.into()),
215	        });
216	
217	        // Camera
218	        let aspect = config.width as f32 / config.height as f32;
219	        let camera = Camera::arcaea_default(aspect, config.height as f32);
220	        let camera_uniform = CameraUniform::from(&camera);
221	
222	        let camera_buffer = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
223	            label: Some("camera_uniform"),
224	            contents: bytemuck::cast_slice(&[camera_uniform]),
225	            usage: wgpu::BufferUsages::UNIFORM | wgpu::BufferUsages::COPY_DST,
226	        });
227	
228	        let camera_bgl = device.create_bind_group_layout(&wgpu::BindGroupLayoutDescriptor {
229	            label: Some("camera_bgl"),
230	            entries: &[wgpu::BindGroupLayoutEntry {
231	                binding: 0,
232	                visibility: wgpu::ShaderStages::VERTEX,
233	                ty: wgpu::BindingType::Buffer {
234	                    ty: wgpu::BufferBindingType::Uniform,
235	                    has_dynamic_offset: false,
236	                    min_binding_size: None,
237	                },
238	                count: None,
239	            }],
240	        });
241	
242	        let camera_bind_group = device.create_bind_group(&wgpu::BindGroupDescriptor {
243	            label: Some("camera_bg"),
244	            layout: &camera_bgl,
245	            entries: &[wgpu::BindGroupEntry {
246	                binding: 0,
247	                resource: camera_buffer.as_entire_binding(),
248	            }],
249	        });
250	
251	        // Textures
252	        let tex_bgl = texture::texture_bind_group_layout(&device);
253	        let tex_white = texture::white_texture(&device, &queue, &tex_bgl);
254	
255	        let extracted = assets_dir.join("extracted");
256	        let load = |name: &str, label: &str| -> wgpu::BindGroup {
257	            let path = extracted.join(name);
258	            if path.exists() {
259	                texture::load_texture(&device, &queue, &tex_bgl, &path, label)
260	            } else {
261	                log::warn!("{name} not found, using white fallback");
262	                texture::white_texture(&device, &queue, &tex_bgl)
263	            }
264	        };
265	
266	        let tex_track = load("track.png", "track");
267	        let tex_divider = load("track_lane_divider.png", "divider");
268	        let tex_judgment = load("track_critical_line.png", "judgment");
269	        let tex_note = load("note.png", "note");
270	        let tex_hold = load("note_hold.png", "note_hold");
271	        let tex_arc_body = load("arc_body.png", "arc_body");
272	        let tex_arc_cap = load("arc_cap.png", "arc_cap");
273	        let tex_sky = load("sfx_l_note.jpg", "sky_note");
274	        let tex_lane_hit = load("lane_hit.png", "lane_hit");
275	        let tex_hit_pure = load("hit_pure.png", "hit_pure");
276	        let tex_hit_far = load("hit_far.png", "hit_far");
277	
278	        // Pipeline (now with texture bind group)
279	        let pipeline_layout = device.create_pipeline_layout(&wgpu::PipelineLayoutDescriptor {
280	            label: Some("pipeline_layout"),
281	            bind_group_layouts: &[&camera_bgl, &tex_bgl],
282	            push_constant_ranges: &[],
283	        });
284	
285	        let pipeline = device.create_render_pipeline(&wgpu::RenderPipelineDescriptor {
286	            label: Some("main"),
287	            layout: Some(&pipeline_layout),
288	            vertex: wgpu::VertexState {
289	                module: &shader,
290	                entry_point: Some("vs_main"),
291	                buffers: &[Vertex::layout()],
292	                compilation_options: Default::default(),
293	            },
294	            fragment: Some(wgpu::FragmentState {
295	                module: &shader,
296	                entry_point: Some("fs_main"),
297	                targets: &[Some(wgpu::ColorTargetState {
298	                    format,
299	                    blend: Some(wgpu::BlendState::ALPHA_BLENDING),
300	                    write_mask: wgpu::ColorWrites::ALL,
301	                })],
302	                compilation_options: Default::default(),
303	            }),
304	            primitive: wgpu::PrimitiveState {
305	                topology: wgpu::PrimitiveTopology::TriangleList,
306	                cull_mode: None,
307	                ..Default::default()
308	            },
309	            depth_stencil: Some(wgpu::DepthStencilState {
310	                format: wgpu::TextureFormat::Depth32Float,
311	                depth_write_enabled: true,
312	                depth_compare: wgpu::CompareFunction::Less,
313	                stencil: wgpu::StencilState::default(),
314	                bias: wgpu::DepthBiasState::default(),
315	            }),
316	            multisample: wgpu::MultisampleState::default(),
317	            multiview: None,
318	            cache: None,
319	        });
320	
321	        // Depth buffer
322	        let depth_view = create_depth_texture(&device, config.width, config.height);
323	
324	        // Static geometry
325	        let track_geo = super::track::build_track_geometry();
326	        let track_surface = create_mesh_buffer(&device, &track_geo.surface.0, &track_geo.surface.1, "track_surface");
327	        let track_dividers = create_mesh_buffer(&device, &track_geo.dividers.0, &track_geo.dividers.1, "track_dividers");
328	        let track_judgment = create_mesh_buffer(&device, &track_geo.judgment.0, &track_geo.judgment.1, "track_judgment");
329	
330	        // Dynamic note buffers (pre-allocated, filled each frame)
