418	    fn upload_mesh(&mut self, mesh: &(Vec<Vertex>, Vec<u32>), which: &str) {
419	        let (verts, idxs) = mesh;
420	        let buf = match which {
421	            "note_taps" => &mut self.note_taps,
422	            "note_holds" => &mut self.note_holds,
423	            "note_arcs" => &mut self.note_arcs,
424	            "note_arc_caps" => &mut self.note_arc_caps,
425	            "note_sky" => &mut self.note_sky,
426	            "fx_lane" => &mut self.fx_lane,
427	            "fx_pure" => &mut self.fx_pure,
428	            "fx_far" => &mut self.fx_far,
429	            _ => return,
430	        };
431	        buf.index_count = idxs.len() as u32;
432	
433	        if verts.is_empty() {
434	            return;
435	        }
436	
437	        let vert_bytes = bytemuck::cast_slice(verts);
438	        let idx_bytes = bytemuck::cast_slice(idxs);
439	
440	        if vert_bytes.len() as u64 > buf.vertex.size() {
441	            buf.vertex = self.device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
442	                label: Some(&format!("{which}_verts")),
443	                contents: vert_bytes,
444	                usage: wgpu::BufferUsages::VERTEX | wgpu::BufferUsages::COPY_DST,
445	            });
446	        } else {
447	            self.queue.write_buffer(&buf.vertex, 0, vert_bytes);
448	        }
449	
450	        if idx_bytes.len() as u64 > buf.index.size() {
451	            buf.index = self.device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
452	                label: Some(&format!("{which}_idxs")),
453	                contents: idx_bytes,
454	                usage: wgpu::BufferUsages::INDEX | wgpu::BufferUsages::COPY_DST,
455	            });
456	        } else {
457	            self.queue.write_buffer(&buf.index, 0, idx_bytes);
458	        }
459	    }
