477	    pub fn render(&mut self) {
478	        // Prepare HUD text before render pass
479	        let screen = [self.config.width, self.config.height];
480	        if let Some(hud) = &mut self.hud {
481	            if self.show_results {
482	                hud.prepare_results(&self.device, &self.queue, screen);
483	            } else {
484	                hud.prepare(&self.device, &self.queue, screen);
485	            }
486	        }
487	
488	        let output = match self.surface.get_current_texture() {
489	            Ok(t) => t,
490	            Err(wgpu::SurfaceError::Lost | wgpu::SurfaceError::Outdated) => {
491	                self.surface.configure(&self.device, &self.config);
492	                return;
493	            }
494	            Err(e) => {
495	                log::error!("surface error: {e:?}");
496	                return;
497	            }
498	        };
499	
500	        let view = output
501	            .texture
502	            .create_view(&wgpu::TextureViewDescriptor::default());
503	
504	        let mut encoder = self
505	            .device
506	            .create_command_encoder(&wgpu::CommandEncoderDescriptor {
507	                label: Some("frame"),
508	            });
509	
510	        self.encode_render_pass(&mut encoder, &view, &self.depth_view);
511	
512	        self.queue.submit(std::iter::once(encoder.finish()));
513	        output.present();
514	    }
