516	    /// Encode the full render pass into the given encoder.
517	    fn encode_render_pass(
518	        &self,
519	        encoder: &mut wgpu::CommandEncoder,
520	        color_view: &wgpu::TextureView,
521	        depth_view: &wgpu::TextureView,
522	    ) {
523	        {
524	            let mut pass = encoder.begin_render_pass(&wgpu::RenderPassDescriptor {
525	                label: Some("main"),
526	                color_attachments: &[Some(wgpu::RenderPassColorAttachment {
527	                    view: color_view,
528	                    resolve_target: None,
529	                    ops: wgpu::Operations {
530	                        load: wgpu::LoadOp::Clear(wgpu::Color {
531	                            r: 0.02,
532	                            g: 0.02,
533	                            b: 0.06,
534	                            a: 1.0,
535	                        }),
536	                        store: wgpu::StoreOp::Store,
537	                    },
538	                })],
539	                depth_stencil_attachment: Some(wgpu::RenderPassDepthStencilAttachment {
540	                    view: depth_view,
541	                    depth_ops: Some(wgpu::Operations {
542	                        load: wgpu::LoadOp::Clear(1.0),
543	                        store: wgpu::StoreOp::Store,
544	                    }),
545	                    stencil_ops: None,
546	                }),
547	                ..Default::default()
548	            });
549	
550	            pass.set_pipeline(&self.pipeline);
551	            pass.set_bind_group(0, &self.camera_bind_group, &[]);
552	
553	            // 1. Track surface (track.png)
554	            pass.set_bind_group(1, &self.tex_track, &[]);
555	            self.draw_mesh(&mut pass, &self.track_surface);
556	
557	            // 2. Lane dividers (track_lane_divider.png)
558	            pass.set_bind_group(1, &self.tex_divider, &[]);
559	            self.draw_mesh(&mut pass, &self.track_dividers);
560	
561	            // 3. Judgment line (track_critical_line.png)
562	            pass.set_bind_group(1, &self.tex_judgment, &[]);
563	            self.draw_mesh(&mut pass, &self.track_judgment);
564	
565	            // 4. Arc bodies (arc_body.png)
566	            pass.set_bind_group(1, &self.tex_arc_body, &[]);
567	            self.draw_mesh(&mut pass, &self.note_arcs);
568	
569	            // 4b. Arc caps (arc_cap.png)
570	            pass.set_bind_group(1, &self.tex_arc_cap, &[]);
571	            self.draw_mesh(&mut pass, &self.note_arc_caps);
572	
573	            // 5. Tap notes (note.png)
574	            pass.set_bind_group(1, &self.tex_note, &[]);
575	            self.draw_mesh(&mut pass, &self.note_taps);
576	
577	            // 6. Hold notes (note_hold.png)
578	            pass.set_bind_group(1, &self.tex_hold, &[]);
579	            self.draw_mesh(&mut pass, &self.note_holds);
580	
581	            // 7. Sky notes (solid cyan — white tex × cyan vertex color)
582	            pass.set_bind_group(1, &self.tex_white, &[]);
583	            self.draw_mesh(&mut pass, &self.note_sky);
584	
585	            // 8. Lane glow (lane_hit.png)
586	            pass.set_bind_group(1, &self.tex_lane_hit, &[]);
587	            self.draw_mesh(&mut pass, &self.fx_lane);
588	
589	            // 9. Pure hit effect (hit_pure.png)
590	            pass.set_bind_group(1, &self.tex_hit_pure, &[]);
591	            self.draw_mesh(&mut pass, &self.fx_pure);
592	
593	            // 10. Far hit effect (hit_far.png)
594	            pass.set_bind_group(1, &self.tex_hit_far, &[]);
595	            self.draw_mesh(&mut pass, &self.fx_far);
596	
597	            // 11. HUD text overlay (combo + score)
598	            if let Some(hud) = &self.hud {
599	                hud.render(&mut pass);
600	            }
601	        }
602	    }
