604	    /// Capture the current frame to an RGBA image.
605	    ///
606	    /// Renders to an offscreen texture and reads back the pixels.
607	    /// Call `update_notes()` before this to set up the scene.
608	    pub fn capture_frame(&self) -> image::RgbaImage {
609	        let width = self.config.width;
610	        let height = self.config.height;
611	        let format = self.config.format;
612	
613	        // Offscreen render target
614	        let capture_tex = self.device.create_texture(&wgpu::TextureDescriptor {
615	            label: Some("capture"),
616	            size: wgpu::Extent3d { width, height, depth_or_array_layers: 1 },
617	            mip_level_count: 1,
618	            sample_count: 1,
619	            dimension: wgpu::TextureDimension::D2,
620	            format,
621	            usage: wgpu::TextureUsages::RENDER_ATTACHMENT | wgpu::TextureUsages::COPY_SRC,
622	            view_formats: &[],
623	        });
624	        let capture_view = capture_tex.create_view(&wgpu::TextureViewDescriptor::default());
625	
626	        // Separate depth buffer for capture (same dimensions)
627	        let capture_depth = create_depth_texture(&self.device, width, height);
628	
629	        let mut encoder = self.device.create_command_encoder(&wgpu::CommandEncoderDescriptor {
630	            label: Some("capture"),
631	        });
632	
633	        self.encode_render_pass(&mut encoder, &capture_view, &capture_depth);
634	
635	        // Copy texture to readback buffer
636	        let bytes_per_pixel = 4u32;
637	        let unpadded_bpr = width * bytes_per_pixel;
638	        let align = wgpu::COPY_BYTES_PER_ROW_ALIGNMENT;
639	        let padded_bpr = (unpadded_bpr + align - 1) / align * align;
640	
641	        let buffer = self.device.create_buffer(&wgpu::BufferDescriptor {
642	            label: Some("capture_readback"),
643	            size: (padded_bpr * height) as u64,
644	            usage: wgpu::BufferUsages::COPY_DST | wgpu::BufferUsages::MAP_READ,
645	            mapped_at_creation: false,
646	        });
647	
648	        encoder.copy_texture_to_buffer(
649	            wgpu::ImageCopyTexture {
650	                texture: &capture_tex,
651	                mip_level: 0,
652	                origin: wgpu::Origin3d::ZERO,
653	                aspect: wgpu::TextureAspect::All,
654	            },
655	            wgpu::ImageCopyBuffer {
656	                buffer: &buffer,
657	                layout: wgpu::ImageDataLayout {
658	                    offset: 0,
659	                    bytes_per_row: Some(padded_bpr),
660	                    rows_per_image: Some(height),
661	                },
662	            },
663	            wgpu::Extent3d { width, height, depth_or_array_layers: 1 },
664	        );
665	
666	        self.queue.submit(std::iter::once(encoder.finish()));
667	
668	        // Map buffer and read pixels
669	        let buffer_slice = buffer.slice(..);
670	        let (sender, receiver) = std::sync::mpsc::channel();
671	        buffer_slice.map_async(wgpu::MapMode::Read, move |result| {
672	            sender.send(result).unwrap();
673	        });
674	        self.device.poll(wgpu::Maintain::Wait);
675	        receiver.recv().unwrap().unwrap();
676	
677	        let data = buffer_slice.get_mapped_range();
678	        let mut pixels = Vec::with_capacity((width * height * 4) as usize);
679	        for chunk in data.chunks(padded_bpr as usize) {
680	            pixels.extend_from_slice(&chunk[..unpadded_bpr as usize]);
681	        }
682	        drop(data);
683	        buffer.unmap();
684	
685	        // BGRA -> RGBA conversion if needed
686	        let is_bgra = matches!(
687	            format,
688	            wgpu::TextureFormat::Bgra8Unorm | wgpu::TextureFormat::Bgra8UnormSrgb
689	        );
690	        if is_bgra {
691	            for pixel in pixels.chunks_exact_mut(4) {
692	                pixel.swap(0, 2);
693	            }
694	        }
695	
696	        image::RgbaImage::from_raw(width, height, pixels).expect("failed to create image from capture")
697	    }
