699	    fn draw_mesh<'a>(&'a self, pass: &mut wgpu::RenderPass<'a>, mesh: &'a MeshBuffer) {
700	        if mesh.index_count == 0 {
701	            return;
702	        }
703	        pass.set_vertex_buffer(0, mesh.vertex.slice(..));
704	        pass.set_index_buffer(mesh.index.slice(..), wgpu::IndexFormat::Uint32);
705	        pass.draw_indexed(0..mesh.index_count, 0, 0..1);
706	    }
707	}
