1	//! Audio engine: low-latency playback with precise position tracking.
2	//!
3	//! Uses cpal for cross-platform output, lewton for ogg/vorbis decoding.
4	//! Audio position serves as the master clock for game timing.
5	
6	pub mod hitsound;
7	
8	use std::fs::File;
9	use std::path::Path;
10	use std::sync::atomic::{AtomicI64, Ordering};
11	use std::sync::Arc;
12	
13	use cpal::traits::{DeviceTrait, HostTrait, StreamTrait};
14	
15	/// Decoded audio samples (interleaved f32, stereo).
16	struct AudioData {
17	    samples: Vec<f32>,
18	    sample_rate: u32,
19	    channels: u16,
20	}
21	
22	/// Audio engine with precise position tracking.
23	pub struct AudioEngine {
24	    _stream: cpal::Stream,
25	    /// Current playback position in samples (shared with audio thread).
26	    position: Arc<AtomicI64>,
27	    sample_rate: u32,
28	    channels: u16,
29	    total_samples: usize,
30	}
31	
32	impl AudioEngine {
33	    /// Load an ogg file and start playback after `delay_ms` of silence.
34	    pub fn play_ogg(path: &Path, delay_ms: i32) -> Result<Self, String> {
35	        let data = decode_ogg(path)?;
36	        Self::play(data, delay_ms)
37	    }
38	
39	    /// Start playback of decoded audio data.
40	    fn play(data: AudioData, delay_ms: i32) -> Result<Self, String> {
41	        let host = cpal::default_host();
42	        let device = host
43	            .default_output_device()
44	            .ok_or("no audio output device")?;
45	        let config = device
46	            .default_output_config()
47	            .map_err(|e| format!("no output config: {e}"))?;
48	
49	        log::info!(
50	            "Audio device: {:?}, format: {:?}",
51	            device.name().unwrap_or_default(),
52	            config,
53	        );
54	
55	        let output_rate = config.sample_rate().0;
56	        let output_channels = config.channels() as u16;
57	
58	        // Resample if needed (simple nearest-neighbor for now)
59	        let samples = if data.sample_rate != output_rate || data.channels != output_channels {
60	            resample(&data.samples, data.sample_rate, data.channels, output_rate, output_channels)
61	        } else {
62	            data.samples.clone()
63	        };
64	
65	        let total_samples = samples.len();
66	
67	        // Add leading silence for delay
68	        let delay_samples = (delay_ms as i64 * output_rate as i64 * output_channels as i64 / 1000) as usize;
69	
70	        // Shared playback position (in output samples, negative = delay)
71	        let position = Arc::new(AtomicI64::new(-(delay_samples as i64)));
72	        let pos_clone = position.clone();
73	
74	        let samples = Arc::new(samples);
75	        let samples_clone = samples.clone();
76	
77	        let stream = device
78	            .build_output_stream(
79	                &config.into(),
80	                move |output: &mut [f32], _: &cpal::OutputCallbackInfo| {
81	                    let mut pos = pos_clone.load(Ordering::Relaxed);
82	                    for frame in output.chunks_exact_mut(output_channels as usize) {
83	                        if pos < 0 {
84	                            // Leading silence
85	                            for s in frame.iter_mut() {
86	                                *s = 0.0;
87	                            }
88	                        } else {
89	                            let idx = pos as usize;
90	                            for (ch, s) in frame.iter_mut().enumerate() {
91	                                *s = samples_clone
92	                                    .get(idx + ch)
93	                                    .copied()
94	                                    .unwrap_or(0.0);
95	                            }
96	                        }
97	                        pos += output_channels as i64;
98	                    }
99	                    pos_clone.store(pos, Ordering::Relaxed);
100	                },
101	                |err| log::error!("audio stream error: {err}"),
102	                None,
103	            )
104	            .map_err(|e| format!("failed to build audio stream: {e}"))?;
105	
106	        stream.play().map_err(|e| format!("failed to start audio: {e}"))?;
107	
108	        log::info!(
109	            "Audio playing: {}Hz {}ch, {} samples ({:.1}s), delay {}ms",
110	            output_rate,
111	            output_channels,
112	            total_samples,
113	            total_samples as f32 / output_rate as f32 / output_channels as f32,
114	            delay_ms,
115	        );
116	
117	        Ok(Self {
118	            _stream: stream,
119	            position,
120	            sample_rate: output_rate,
121	            channels: output_channels,
122	            total_samples,
123	        })
124	    }
125	
126	    /// Current playback position in milliseconds.
127	    /// Negative values indicate lead-in silence.
128	    pub fn position_ms(&self) -> i32 {
129	        let pos = self.position.load(Ordering::Relaxed);
130	        (pos * 1000 / self.sample_rate as i64 / self.channels as i64) as i32
131	    }
132	
133	    /// Whether playback has finished.
134	    pub fn is_finished(&self) -> bool {
135	        let pos = self.position.load(Ordering::Relaxed);
136	        pos >= self.total_samples as i64
137	    }
138	}
139	
140	/// Decode an ogg/vorbis file to interleaved f32 samples.
141	fn decode_ogg(path: &Path) -> Result<AudioData, String> {
142	    let file = File::open(path).map_err(|e| format!("cannot open {}: {e}", path.display()))?;
143	    let mut reader = lewton::inside_ogg::OggStreamReader::new(file)
144	        .map_err(|e| format!("ogg parse error: {e}"))?;
145	
146	    let sample_rate = reader.ident_hdr.audio_sample_rate;
147	    let channels = reader.ident_hdr.audio_channels as u16;
148	
149	    let mut samples = Vec::new();
150	    while let Some(packet) = reader
151	        .read_dec_packet_itl()
152	        .map_err(|e| format!("vorbis decode error: {e}"))?
153	    {
154	        for &s in &packet {
155	            samples.push(s as f32 / 32768.0);
156	        }
157	    }
158	
159	    log::info!(
160	        "Decoded ogg: {}Hz {}ch, {} samples ({:.1}s)",
161	        sample_rate,
162	        channels,
163	        samples.len(),
164	        samples.len() as f32 / sample_rate as f32 / channels as f32,
165	    );
166	
167	    Ok(AudioData {
168	        samples,
169	        sample_rate,
170	        channels,
171	    })
172	}
173	
174	/// Simple nearest-neighbor resample + channel conversion.
175	pub(crate) fn resample(
176	    src: &[f32],
177	    src_rate: u32,
178	    src_ch: u16,
179	    dst_rate: u32,
180	    dst_ch: u16,
181	) -> Vec<f32> {
182	    let src_frames = src.len() / src_ch as usize;
183	    let dst_frames = (src_frames as u64 * dst_rate as u64 / src_rate as u64) as usize;
184	    let mut out = Vec::with_capacity(dst_frames * dst_ch as usize);
185	
186	    for i in 0..dst_frames {
187	        let src_frame = (i as u64 * src_rate as u64 / dst_rate as u64) as usize;
188	        for ch in 0..dst_ch as usize {
189	            let src_idx = src_frame * src_ch as usize + ch.min(src_ch as usize - 1);
190	            out.push(src.get(src_idx).copied().unwrap_or(0.0));
191	        }
192	    }
193	
194	    out
195	}
196

