use std::path::Path;
use std::sync::{Arc, Mutex};

use cpal::traits::{DeviceTrait, HostTrait, StreamTrait};

use super::resample;

struct Voice {
    samples: Arc<Vec<f32>>,
    cursor: usize,
}

pub struct HitsoundEngine {
    tap_samples: Arc<Vec<f32>>,
    arc_samples: Arc<Vec<f32>>,
    voices: Arc<Mutex<Vec<Voice>>>,
    _stream: cpal::Stream,
}

const MAX_VOICES: usize = 16;

impl HitsoundEngine {
    pub fn new() -> Option<Self> {
        let tap_path = Path::new("assets/extracted/tap.wav");
        let arc_path = Path::new("assets/extracted/arc.wav");

        if !tap_path.exists() {
            log::warn!("hitsound: tap.wav not found at {}", tap_path.display());
            return None;
        }
        if !arc_path.exists() {
            log::warn!("hitsound: arc.wav not found at {}", arc_path.display());
            return None;
        }

        let host = cpal::default_host();
        let device = host.default_output_device()?;
        let config = device.default_output_config().ok()?;
        let output_rate = config.sample_rate().0;
        let output_channels = config.channels() as u16;

        let tap_samples = Arc::new(Self::load_wav(tap_path, output_rate, output_channels)?);
        let arc_samples = Arc::new(Self::load_wav(arc_path, output_rate, output_channels)?);

        log::info!(
            "hitsound: loaded tap({} samples) arc({} samples) @{}Hz {}ch",
            tap_samples.len(),
            arc_samples.len(),
            output_rate,
            output_channels,
        );

        let voices: Arc<Mutex<Vec<Voice>>> = Arc::new(Mutex::new(Vec::new()));
        let voices_clone = voices.clone();

        let stream = device
            .build_output_stream(
                &config.into(),
                move |output: &mut [f32], _: &cpal::OutputCallbackInfo| {
                    for s in output.iter_mut() {
                        *s = 0.0;
                    }

                    let mut voices = voices_clone.lock().unwrap();

                    for voice in voices.iter_mut() {
                        for s in output.iter_mut() {
                            if voice.cursor < voice.samples.len() {
                                *s += voice.samples[voice.cursor];
                                voice.cursor += 1;
                            }
                        }
                    }

                    voices.retain(|v| v.cursor < v.samples.len());
                },
                |err| log::error!("hitsound stream error: {err}"),
                None,
            )
            .ok()?;

        stream.play().ok()?;

        Some(Self {
            tap_samples,
            arc_samples,
            voices,
            _stream: stream,
        })
    }

    pub fn play_tap(&self) {
        self.play(self.tap_samples.clone());
    }

    pub fn play_arc(&self) {
        self.play(self.arc_samples.clone());
    }

    fn play(&self, samples: Arc<Vec<f32>>) {
        let mut voices = self.voices.lock().unwrap();
        if voices.len() >= MAX_VOICES {
            voices.remove(0);
        }
        voices.push(Voice { samples, cursor: 0 });
    }

    fn load_wav(path: &Path, target_rate: u32, target_channels: u16) -> Option<Vec<f32>> {
        let mut reader = hound::WavReader::open(path)
            .map_err(|e| log::error!("hitsound: failed to open {}: {e}", path.display()))
            .ok()?;

        let spec = reader.spec();
        let src_rate = spec.sample_rate;
        let src_channels = spec.channels as u16;

        let samples: Vec<f32> = match spec.sample_format {
            hound::SampleFormat::Int => {
                let max_val = (1u32 << (spec.bits_per_sample - 1)) as f32;
                reader
                    .samples::<i32>()
                    .filter_map(|s| s.ok())
                    .map(|s| s as f32 / max_val)
                    .collect()
            }
            hound::SampleFormat::Float => {
                reader
                    .samples::<f32>()
                    .filter_map(|s| s.ok())
                    .collect()
            }
        };

        if src_rate != target_rate || src_channels != target_channels {
            Some(resample(&samples, src_rate, src_channels, target_rate, target_channels))
        } else {
            Some(samples)
        }
    }
}

