use crate::judgment::ScoreState;
use glyphon::{
    Attrs, Buffer, Cache, Color, Family, FontSystem, Metrics, Resolution,
    Shaping, SwashCache, TextArea, TextAtlas, TextBounds, TextRenderer, Viewport,
    Weight,
};

pub struct HudRenderer {
    font_system: FontSystem,
    swash_cache: SwashCache,
    #[allow(dead_code)]
    cache: Cache,
    atlas: TextAtlas,
    viewport: Viewport,
    renderer: TextRenderer,
    combo_buffer: Buffer,
    score_buffer: Buffer,
    results_buffer: Buffer,
    combo_text: String,
    score_text: String,
    combo_color: Color,
    results_text: String,
}

impl HudRenderer {
    pub fn new(
        device: &wgpu::Device,
        queue: &wgpu::Queue,
        format: wgpu::TextureFormat,
    ) -> Option<Self> {
        let mut font_system = FontSystem::new();

        let font_path = std::path::Path::new("assets/extracted/Exo-SemiBold.ttf");
        if font_path.exists() {
            if let Ok(data) = std::fs::read(font_path) {
                font_system.db_mut().load_font_data(data);
                log::info!("hud: loaded Exo-SemiBold.ttf");
            }
        } else {
            log::warn!("hud: Exo-SemiBold.ttf not found, using system fallback");
        }

        let swash_cache = SwashCache::new();
        let cache = Cache::new(device);
        let mut atlas = TextAtlas::new(device, queue, &cache, format);
        let viewport = Viewport::new(device, &cache);
        let renderer = TextRenderer::new(
            &mut atlas,
            device,
            wgpu::MultisampleState::default(),
            Some(wgpu::DepthStencilState {
                format: wgpu::TextureFormat::Depth32Float,
                depth_write_enabled: false,
                depth_compare: wgpu::CompareFunction::Always,
                stencil: wgpu::StencilState::default(),
                bias: wgpu::DepthBiasState::default(),
            }),
        );

        let combo_buffer = Buffer::new(&mut font_system, Metrics::new(48.0, 52.0));
        let score_buffer = Buffer::new(&mut font_system, Metrics::new(24.0, 28.0));
        let results_buffer = Buffer::new(&mut font_system, Metrics::new(32.0, 40.0));

        Some(Self {
            font_system,
            swash_cache,
            cache,
            atlas,
            viewport,
            renderer,
            combo_buffer,
            score_buffer,
            results_buffer,
            combo_text: String::new(),
            score_text: String::from("00000000"),
            combo_color: Color::rgba(150, 180, 255, 180),
            results_text: String::new(),
        })
    }

    pub fn set_combo(&mut self, combo: u32, flash: f32) {
        if combo > 0 {
            self.combo_text = format!("{}", combo);
            self.combo_color = Color::rgba(150, 180, 255, 180);
        } else if flash > 0.0 {
            let alpha = (flash * 255.0) as u8;
            self.combo_color = Color::rgba(255, 50, 50, alpha);
        } else {
            self.combo_text.clear();
        }
    }

    pub fn set_score(&mut self, score: u64) {
        self.score_text = format!("{:08}", score.min(99_999_999));
    }

    pub fn set_results(&mut self, score: &ScoreState) {
        self.results_text = format!(
            "SCORE\n{:08}\n\nPURE    {} (+{})\nFAR     {}\nLOST    {}\n\nMAX COMBO  {}",
            score.score().min(99_999_999),
            score.pure_max + score.pure,
            score.pure_max,
            score.far,
            score.lost,
            score.max_combo,
        );
    }

    pub fn prepare_results(
        &mut self,
        device: &wgpu::Device,
        queue: &wgpu::Queue,
        screen: [u32; 2],
    ) {
        let [sw, sh] = screen;
        let sw_f = sw as f32;
        let sh_f = sh as f32;

        let attrs = Attrs::new()
            .family(Family::Name("Exo SemiBold"))
            .weight(Weight::SEMIBOLD);

        let size = sh_f * 0.045;
        self.results_buffer.set_metrics(
            &mut self.font_system,
            Metrics::new(size, size * 1.5),
        );
        self.results_buffer
            .set_size(&mut self.font_system, Some(sw_f * 0.8), Some(sh_f * 0.8));
        self.results_buffer.set_text(
            &mut self.font_system,
            &self.results_text,
            attrs,
            Shaping::Advanced,
        );
        self.results_buffer
            .shape_until_scroll(&mut self.font_system, false);

        let text_height = self.results_buffer.layout_runs().count() as f32 * size * 1.5;
        let top = (sh_f - text_height) / 2.0;
        let text_width = self
            .results_buffer
            .layout_runs()
            .fold(0.0f32, |w, run| w.max(run.line_w));
        let left = (sw_f - text_width) / 2.0;

        let areas = vec![TextArea {
            buffer: &self.results_buffer,
            left,
            top,
            scale: 1.0,
            bounds: TextBounds {
                left: 0,
                top: 0,
                right: sw as i32,
                bottom: sh as i32,
            },
            default_color: Color::rgba(255, 255, 255, 255),
            custom_glyphs: &[],
        }];

        self.viewport
            .update(queue, Resolution { width: sw, height: sh });

        self.renderer
            .prepare(
                device,
                queue,
                &mut self.font_system,
                &mut self.atlas,
                &self.viewport,
                areas,
                &mut self.swash_cache,
            )
            .unwrap();
    }

    pub fn prepare(
        &mut self,
        device: &wgpu::Device,
        queue: &wgpu::Queue,
        screen: [u32; 2],
    ) {
        let [sw, sh] = screen;
        let sw_f = sw as f32;
        let sh_f = sh as f32;

        let attrs = Attrs::new()
            .family(Family::Name("Exo SemiBold"))
            .weight(Weight::SEMIBOLD);

        // Combo: large, centered
        let combo_size = sh_f * 0.08;
        self.combo_buffer.set_metrics(
            &mut self.font_system,
            Metrics::new(combo_size, combo_size * 1.1),
        );
        self.combo_buffer
            .set_size(&mut self.font_system, Some(sw_f), Some(combo_size * 2.0));
        self.combo_buffer.set_text(
            &mut self.font_system,
            &self.combo_text,
            attrs,
            Shaping::Advanced,
        );
        self.combo_buffer
            .shape_until_scroll(&mut self.font_system, false);

        // Score: smaller, right-aligned
        let score_size = sh_f * 0.04;
        self.score_buffer.set_metrics(
            &mut self.font_system,
            Metrics::new(score_size, score_size * 1.1),
        );
        self.score_buffer
            .set_size(&mut self.font_system, Some(sw_f), Some(score_size * 2.0));
        self.score_buffer.set_text(
            &mut self.font_system,
            &self.score_text,
            attrs,
            Shaping::Advanced,
        );
        self.score_buffer
            .shape_until_scroll(&mut self.font_system, false);

        // Combo position: centered horizontally, ~55% down
        let combo_width = self
            .combo_buffer
            .layout_runs()
            .fold(0.0f32, |w, run| w.max(run.line_w));
        let combo_left = (sw_f - combo_width) / 2.0;
        let combo_top = sh_f * 0.55;

        // Score position: right-aligned, top
        let score_width = self
            .score_buffer
            .layout_runs()
            .fold(0.0f32, |w, run| w.max(run.line_w));
        let score_left = sw_f - score_width - 20.0;
        let score_top = 20.0;

        let mut areas: Vec<TextArea> = Vec::new();

        if !self.combo_text.is_empty() {
            areas.push(TextArea {
                buffer: &self.combo_buffer,
                left: combo_left,
                top: combo_top,
                scale: 1.0,
                bounds: TextBounds {
                    left: 0,
                    top: 0,
                    right: sw as i32,
                    bottom: sh as i32,
                },
                default_color: self.combo_color,
                custom_glyphs: &[],
            });
        }

        areas.push(TextArea {
            buffer: &self.score_buffer,
            left: score_left,
            top: score_top,
            scale: 1.0,
            bounds: TextBounds {
                left: 0,
                top: 0,
                right: sw as i32,
                bottom: sh as i32,
            },
            default_color: Color::rgba(255, 255, 255, 255),
            custom_glyphs: &[],
        });

        self.viewport
            .update(queue, Resolution { width: sw, height: sh });

        self.renderer
            .prepare(
                device,
                queue,
                &mut self.font_system,
                &mut self.atlas,
                &self.viewport,
                areas,
                &mut self.swash_cache,
            )
            .unwrap();
    }

    pub fn render<'a>(&'a self, pass: &mut wgpu::RenderPass<'a>) {
        self.renderer
            .render(&self.atlas, &self.viewport, pass)
            .unwrap();
    }
}

use std::path::Path;

/// Load an image file and create a wgpu texture + bind group.
pub fn load_texture(
    device: &wgpu::Device,
    queue: &wgpu::Queue,
    layout: &wgpu::BindGroupLayout,
    path: &Path,
    label: &str,
) -> wgpu::BindGroup {
    let img = image::open(path)
        .unwrap_or_else(|e| panic!("failed to load texture {}: {e}", path.display()))
        .to_rgba8();
    create_bind_group(device, queue, layout, &img, label)
}

/// Create a 1x1 white texture for untextured (color-only) geometry.
pub fn white_texture(
    device: &wgpu::Device,
    queue: &wgpu::Queue,
    layout: &wgpu::BindGroupLayout,
) -> wgpu::BindGroup {
    let img = image::RgbaImage::from_pixel(1, 1, image::Rgba([255, 255, 255, 255]));
    create_bind_group(device, queue, layout, &img, "white")
}

fn create_bind_group(
    device: &wgpu::Device,
    queue: &wgpu::Queue,
    layout: &wgpu::BindGroupLayout,
    img: &image::RgbaImage,
    label: &str,
) -> wgpu::BindGroup {
    let (width, height) = img.dimensions();
    let size = wgpu::Extent3d {
        width,
        height,
        depth_or_array_layers: 1,
    };

    let texture = device.create_texture(&wgpu::TextureDescriptor {
        label: Some(label),
        size,
        mip_level_count: 1,
        sample_count: 1,
        dimension: wgpu::TextureDimension::D2,
        format: wgpu::TextureFormat::Rgba8UnormSrgb,
        usage: wgpu::TextureUsages::TEXTURE_BINDING | wgpu::TextureUsages::COPY_DST,
        view_formats: &[],
    });

    queue.write_texture(
        wgpu::ImageCopyTexture {
            texture: &texture,
            mip_level: 0,
            origin: wgpu::Origin3d::ZERO,
            aspect: wgpu::TextureAspect::All,
        },
        img.as_raw(),
        wgpu::ImageDataLayout {
            offset: 0,
            bytes_per_row: Some(4 * width),
            rows_per_image: Some(height),
        },
        size,
    );

    let view = texture.create_view(&wgpu::TextureViewDescriptor::default());
    let sampler = device.create_sampler(&wgpu::SamplerDescriptor {
        address_mode_u: wgpu::AddressMode::ClampToEdge,
        address_mode_v: wgpu::AddressMode::ClampToEdge,
        mag_filter: wgpu::FilterMode::Linear,
        min_filter: wgpu::FilterMode::Linear,
        ..Default::default()
    });

    device.create_bind_group(&wgpu::BindGroupDescriptor {
        label: Some(label),
        layout,
        entries: &[
            wgpu::BindGroupEntry {
                binding: 0,
                resource: wgpu::BindingResource::TextureView(&view),
            },
            wgpu::BindGroupEntry {
                binding: 1,
                resource: wgpu::BindingResource::Sampler(&sampler),
            },
        ],
    })
}

/// Create the bind group layout for textures (group 1).
pub fn texture_bind_group_layout(device: &wgpu::Device) -> wgpu::BindGroupLayout {
    device.create_bind_group_layout(&wgpu::BindGroupLayoutDescriptor {
        label: Some("texture_bgl"),
        entries: &[
            wgpu::BindGroupLayoutEntry {
                binding: 0,
                visibility: wgpu::ShaderStages::FRAGMENT,
                ty: wgpu::BindingType::Texture {
                    multisampled: false,
                    view_dimension: wgpu::TextureViewDimension::D2,
                    sample_type: wgpu::TextureSampleType::Float { filterable: true },
                },
                count: None,
            },
            wgpu::BindGroupLayoutEntry {
                binding: 1,
                visibility: wgpu::ShaderStages::FRAGMENT,
                ty: wgpu::BindingType::Sampler(wgpu::SamplerBindingType::Filtering),
                count: None,
            },
        ],
    })
}

