use crate::chart::types::*;
use crate::timing::GameClock;

use super::vertex::Vertex;

// RE-confirmed track parameters (Arcaea 6.13.10c)
pub(crate) const LANE_WIDTH: f32 = 4.25;
pub(crate) const TRACK_WIDTH: f32 = 4.0 * LANE_WIDTH; // 17.0
pub(crate) const TRACK_HALF_WIDTH: f32 = TRACK_WIDTH / 2.0; // 8.5
pub(crate) const TRACK_LENGTH_FORWARD: f32 = 100.0; // z=0 to z=-100
pub(crate) const TRACK_LENGTH_BACKWARD: f32 = 53.5; // z=0 to z=+53.5
const TRACK_TOTAL_LENGTH: f32 = TRACK_LENGTH_FORWARD + TRACK_LENGTH_BACKWARD;

const NOTE_Y: f32 = 0.01;

// Tap/Hold mesh dimensions (ArcCreate Tap.fbx / Hold.fbx cross-verified).
// X: ±1.9 (width = 3.8, ~89% of lane), Z: -1.0..0.0 (depth = 1.0).
// Width is FIXED; only depth is z-dependent scaled.
pub(crate) const NOTE_HALF_WIDTH: f32 = 1.9;
pub(crate) const NOTE_WIDTH: f32 = NOTE_HALF_WIDTH * 2.0; // 3.8
pub(crate) const NOTE_BASE_DEPTH: f32 = 1.0;

/// Tap note z-dependent scale factor (applied to Z/depth axis ONLY).
/// Source: Ghidra -- RenderTapNote::updatePosition (Arcaea 6.13.10c)
/// ArcCreate: ArcFormula.CalculateTapSizeScalar, applied to scl.z only
fn tap_note_scale(z: f32) -> f32 {
    if z <= 0.0 {
        (1.5 + 6.25 * (-z) / TRACK_LENGTH_FORWARD).abs()
    } else {
        (1.5 + 7.25 * z / TRACK_LENGTH_BACKWARD).abs()
    }
}

/// Note fade-out at track edges.
/// Source: ArcCreate Values.NoteFadeOutLength = 10
const NOTE_FADE_OUT_LENGTH: f32 = 10.0;

fn note_fade_alpha(z: f32) -> f32 {
    if z <= 0.0 {
        ((TRACK_LENGTH_FORWARD + z) / NOTE_FADE_OUT_LENGTH).clamp(0.0, 1.0)
    } else {
        ((TRACK_LENGTH_BACKWARD - z) / NOTE_FADE_OUT_LENGTH).clamp(0.0, 1.0)
    }
}

// ArcTap (sky note) mesh dimensions (ArcCreate ArcTaps.fbx).
// Flat quad: X=±2.125 (width=4.25 = lane width), Z=-1.2..0.0.
// No z-dependent scaling. X scaled by width property (default 1.0).
pub(crate) const ARCTAP_HALF_WIDTH: f32 = 2.125;
pub(crate) const ARCTAP_DEPTH: f32 = 1.2;

// Hold rendering. Source: ArcCreate cross-verification.
const HOLD_MAX_ALPHA: f32 = 0.8627;

// Arc body rendering. Source: ArcCreate cross-verification.
pub(crate) const ARC_BODY_WIDTH: f32 = 0.9;
pub(crate) const TRACE_BODY_WIDTH: f32 = 0.15;
pub(crate) const ARC_SEGMENT_MS: f32 = 1000.0 / 14.0; // ~71.43ms per segment
const ARC_MAX_ALPHA: f32 = 0.8824;
const TRACE_ALPHA_SCALAR: f32 = 0.4779; // ArcCreate Values.TraceAlphaScalar

