```rust
use crate::render::track::{LANE_WIDTH, TRACK_HALF_WIDTH};
use glam::{Mat4, Vec4};

/// Map screen touch coordinates to a lane number (1-4).
///
/// Unprojects the touch point through the inverse view-projection matrix
/// to find where it hits the track plane (y=0), then maps the world-space
/// x coordinate to the nearest lane.
pub fn touch_to_lane(
    touch_x: f32,
    touch_y: f32,
    screen_width: f32,
    screen_height: f32,
    inv_view_proj: &Mat4,
) -> Option<u8> {
    // Screen pixels → NDC
    let ndc_x = 2.0 * touch_x / screen_width - 1.0;
    let ndc_y = 1.0 - 2.0 * touch_y / screen_height;

    // Unproject near/far clip points to world space
    let near = *inv_view_proj * Vec4::new(ndc_x, ndc_y, 0.0, 1.0);
    let far = *inv_view_proj * Vec4::new(ndc_x, ndc_y, 1.0, 1.0);
    let near = near.truncate() / near.w;
    let far = far.truncate() / far.w;

    // Ray-plane intersection with y=0
    let dir = far - near;
    if dir.y.abs() < 1e-6 {
        return None;
    }
    let t = -near.y / dir.y;
    if t < 0.0 {
        return None;
    }
    let world_x = near.x + t * dir.x;

    // World x → lane (inverse of lane_to_x: -LANE_WIDTH * lane + LANE_WIDTH * 2.5)
    let lane = ((-world_x + LANE_WIDTH * 2.5) / LANE_WIDTH).round() as i32;
    Some(lane.clamp(1, 4) as u8)
}
```

