#[cfg(test)]
mod tests {
    use super::*;
    use crate::render::camera::Camera;

    fn test_camera() -> Camera {
        Camera::arcaea_default(9.0 / 16.0, 1600.0)
    }

    #[test]
    fn touch_center_maps_to_lane_2_or_3() {
        let cam = test_camera();
        let inv = cam.inv_view_proj();
        // Touch dead center of screen
        let lane = touch_to_lane(450.0, 800.0, 900.0, 1600.0, &inv);
        assert!(lane == Some(2) || lane == Some(3), "center touch should be lane 2 or 3, got {lane:?}");
    }

    #[test]
    fn touch_left_maps_to_lane_4() {
        let cam = test_camera();
        let inv = cam.inv_view_proj();
        // Touch far left of screen
        let lane = touch_to_lane(50.0, 1400.0, 900.0, 1600.0, &inv);
        assert_eq!(lane, Some(4), "far left touch should be lane 4");
    }

    #[test]
    fn touch_right_maps_to_lane_1() {
        let cam = test_camera();
        let inv = cam.inv_view_proj();
        // Touch far right of screen
        let lane = touch_to_lane(850.0, 1400.0, 900.0, 1600.0, &inv);
        assert_eq!(lane, Some(1), "far right touch should be lane 1");
    }

    #[test]
    fn x_to_lane_roundtrip() {
        // Verify lane_to_x → touch_to_lane roundtrip for each lane center
        let cam = test_camera();
        let vp = cam.view_proj();
        let inv = cam.inv_view_proj();

        for expected_lane in 1u8..=4 {
            let world_x = crate::render::track::lane_to_x(expected_lane as f32);
            // Project lane center to screen
            let clip = vp * Vec4::new(world_x, 0.01, 0.0, 1.0);
            let ndc = clip.truncate() / clip.w;
            let sx = (ndc.x + 1.0) / 2.0 * 900.0;
            let sy = (1.0 - ndc.y) / 2.0 * 1600.0;

            let lane = touch_to_lane(sx, sy, 900.0, 1600.0, &inv);
            assert_eq!(
                lane,
                Some(expected_lane),
                "lane_to_x({expected_lane}) → screen ({sx:.0}, {sy:.0}) → should map back to lane {expected_lane}"
            );
        }
    }
}
