use std::path::PathBuf;

pub struct AssetLoader {
    #[cfg(not(target_os = "android"))]
    base_dir: PathBuf,
    #[cfg(target_os = "android")]
    app: android_activity::AndroidApp,
}

impl AssetLoader {
    #[cfg(not(target_os = "android"))]
    pub fn new(base_dir: PathBuf) -> Self {
        Self { base_dir }
    }

    #[cfg(target_os = "android")]
    pub fn new(app: &android_activity::AndroidApp) -> Self {
        Self { app: app.clone() }
    }

    pub fn load_bytes(&self, path: &str) -> Result<Vec<u8>, String> {
        self.load_bytes_impl(path)
    }

    pub fn load_string(&self, path: &str) -> Result<String, String> {
        let bytes = self.load_bytes(path)?;
        String::from_utf8(bytes).map_err(|e| format!("utf8 error in {path}: {e}"))
    }

    #[cfg(not(target_os = "android"))]
    fn load_bytes_impl(&self, path: &str) -> Result<Vec<u8>, String> {
        let full = self.base_dir.join(path);
        std::fs::read(&full).map_err(|e| format!("{}: {e}", full.display()))
    }

    #[cfg(target_os = "android")]
    fn load_bytes_impl(&self, path: &str) -> Result<Vec<u8>, String> {
        use std::ffi::CString;
        use std::io::Read;
        let cpath = CString::new(path).map_err(|e| e.to_string())?;
        let mgr = self.app.asset_manager();
        let mut asset = mgr
            .open(&cpath)
            .ok_or_else(|| format!("asset not found: {path}"))?;
        let mut buf = Vec::new();
        asset.read_to_end(&mut buf).map_err(|e| format!("{path}: {e}"))?;
        Ok(buf)
    }
}
```

