/// Decode ogg/vorbis from in-memory bytes.
fn decode_ogg_from_bytes(data: Vec<u8>) -> Result<AudioData, String> {
    let cursor = std::io::Cursor::new(data);
    let mut reader = lewton::inside_ogg::OggStreamReader::new(cursor)
        .map_err(|e| format!("ogg parse error: {e}"))?;

    let sample_rate = reader.ident_hdr.audio_sample_rate;
    let channels = reader.ident_hdr.audio_channels as u16;

    let mut samples = Vec::new();
    while let Some(packet) = reader
        .read_dec_packet_itl()
        .map_err(|e| format!("vorbis decode error: {e}"))?
    {
        for &s in &packet {
            samples.push(s as f32 / 32768.0);
        }
    }

    log::info!(
        "Decoded ogg (memory): {}Hz {}ch, {} samples ({:.1}s)",
        sample_rate,
        channels,
        samples.len(),
        samples.len() as f32 / sample_rate as f32 / channels as f32,
    );

    Ok(AudioData {
        samples,
        sample_rate,
        channels,
    })
}
```

