}
```

With:
```rust
let mut font_system = FontSystem::new();

match assets.load_bytes("extracted/Exo-SemiBold.ttf") {
    Ok(data) => {
        font_system.db_mut().load_font_data(data);
        log::info!("hud: loaded Exo-SemiBold.ttf");
    }
    Err(e) => log::warn!("hud: {e}, using system fallback"),
}
```

### Step 2: Change Gpu::new in src/render/gpu.rs

Change signature from:
```rust
pub async fn new(window: Arc<Window>, assets_dir: &Path) -> Self {
```
to:
```rust
pub async fn new(window: Arc<Window>, assets: &crate::assets::AssetLoader) -> Self {
```

Replace the texture loading block (around lines 252-276). Currently:
```rust
let tex_bgl = texture::texture_bind_group_layout(&device);
let tex_white = texture::white_texture(&device, &queue, &tex_bgl);

