### Step 4: Update resumed() in src/app.rs

Replace the entire resumed() method body with:

```rust
fn resumed(&mut self, event_loop: &ActiveEventLoop) {
    if self.state.is_some() {
        return;
    }

    let window_attrs = Window::default_attributes().with_title("BetterArc");
    let window = Arc::new(
        event_loop
            .create_window(window_attrs)
            .expect("failed to create window"),
    );

    // Create asset loader
    #[cfg(target_os = "android")]
    let assets = crate::assets::AssetLoader::new(&self.android_app);
    #[cfg(not(target_os = "android"))]
    let assets = crate::assets::AssetLoader::new(std::path::PathBuf::from("assets"));

    // Load chart
    let chart_str = if let Some(path) = &self.chart_path {
        std::fs::read_to_string(path).expect("failed to read chart file")
    } else {
        assets
            .load_string("charts/test.aff")
            .unwrap_or_else(|_| include_str!("../assets/charts/test.aff").to_string())
    };
    let chart = crate::chart::parse(&chart_str).expect("failed to parse chart");
    log::info!(
        "chart loaded: {} taps, {} holds, {} arcs",
        chart.groups[0].taps.len(),
        chart.groups[0].holds.len(),
        chart.groups[0].arcs.len(),
    );

    let mut clock = GameClock::new(&chart);

    // Load audio
    if let Some(audio_path) = &self.audio_path {
        let path = std::path::Path::new(audio_path);
        if path.exists() {
            match AudioEngine::play_ogg(path, LEAD_IN_MS) {
                Ok(engine) => {
                    log::info!("audio loaded from {}", audio_path);
                    clock.set_audio(engine);
                }
                Err(e) => log::error!("failed to load audio: {e}"),
            }
        } else {
            log::warn!("audio file not found: {}", audio_path);
        }
    } else {
        match assets.load_bytes("charts/audio.ogg") {
            Ok(bytes) => match AudioEngine::play_ogg_bytes(bytes, LEAD_IN_MS) {
                Ok(engine) => {
                    log::info!("audio loaded from assets");
                    clock.set_audio(engine);
                }
                Err(e) => log::error!("failed to play audio: {e}"),
            },
            Err(e) => log::info!("no audio in assets: {e}"),
        }
    }

    let input = InputManager::new();
    let judge = GreedyJudge::new(&chart);
    let hitsound = HitsoundEngine::with_assets(&assets);
    if hitsound.is_some() {
        log::info!("hitsound engine initialized");
    }
    let gpu = pollster::block_on(Gpu::new(window.clone(), &assets));

    self.state = Some(AppState {
        window,
        gpu,
        chart,
        clock,
        input,
        judge,
        hit_effects: Vec::new(),
        hitsound,
        last_combo: 0,
        combo_flash: 0.0,
        last_frame: Instant::now(),
        result_shown: false,
    });
    log::info!("app initialized");
}
```

Remove `use std::path::{Path, PathBuf};` from app.rs imports (no longer needed at top level).

### Step 5: Update lib.rs android_main

Change the android_main function in src/lib.rs. Current code:
```rust
let mut app = self::app::App::new(None, None);
```

Replace with:
```rust
let mut game = self::app::App::new(app);
```

And change `with_android_app(app)` to `with_android_app(app.clone())` since App::new also needs the app handle:
```rust
let event_loop = EventLoop::builder()
    .with_android_app(app.clone())
    .build()
    .expect("failed to create event loop");

let mut game = self::app::App::new(app);
event_loop.run_app(&mut game).expect("event loop error");
```

### Step 6: Clean up old code in hitsound.rs

Remove the old `HitsoundEngine::new()` method (the one that takes no args and uses Path::new("assets/extracted/...")).
Remove the old `load_wav` method that takes `&Path`.
Remove `use std::path::Path;` from hitsound.rs imports.

### Step 7: Verify

Run: `cargo check`
Run: `cargo test`
Both should pass.

### Step 8: Commit

```bash
git add src/render/gpu.rs src/render/hud.rs src/audio/hitsound.rs src/app.rs src/lib.rs
git commit -m "feat: wire AssetLoader through all subsystems

GPU textures, audio, hitsound, HUD font all load via AssetLoader.
App creates AssetLoader from filesystem (desktop) or AndroidApp (Android).
Old path-based HitsoundEngine::new removed."
```

## Context

BetterArc is an Arcaea rhythm game simulator in Rust. This task connects the AssetLoader (created in Task 1) to all subsystems. The _from_bytes variants were added in Tasks 2-4. This task switches everything over and removes old filesystem-based loading.

Key types already available:
- `crate::assets::AssetLoader` — has `load_bytes(&str) -> Result<Vec<u8>>`, `load_string(&str) -> Result<String>`
- `texture::load_texture_from_bytes(device, queue, layout, &[u8], label) -> BindGroup`
- `AudioEngine::play_ogg_bytes(Vec<u8>, i32) -> Result<Self>`
- `HitsoundEngine::with_assets(&AssetLoader) -> Option<Self>`
- `Camera::inv_view_proj() -> Mat4` (already added in camera.rs)

The `HitsoundEngine::new()` old constructor and `load_wav(&Path, ...)` should be removed since `with_assets` replaces them entirely.

