pub fn run_app() {
    let args: Vec<String> = std::env::args().collect();
    // Usage: better-arc [chart.aff] [audio.ogg]
    let chart_path = args.get(1).cloned();
    let audio_path = args.get(2).cloned();

    if chart_path.is_some() {
        log::info!("chart: {}", chart_path.as_deref().unwrap());
    }
    if audio_path.is_some() {
        log::info!("audio: {}", audio_path.as_deref().unwrap());
    }

    let event_loop = EventLoop::new().expect("failed to create event loop");
    let mut app = App::new(chart_path, audio_path);
    event_loop.run_app(&mut app).expect("event loop error");
}

